import { useEffect, useState } from 'react';
import Head from 'next/head';
import Header from '../components/Header';
import Footer from '../components/Footer';
import { supabase } from '../config/supabase';

export default function Certificados() {
  const [certificados, setCertificados] = useState([]);
  const [filtroAtivo, setFiltroAtivo] = useState('all');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchCertificados = async () => {
      const { data, error } = await supabase
        .from('certificados')
        .select('*')
        .order('data_conclusao', { ascending: false });
      
      if (!error && data) setCertificados(data);
      setLoading(false);
    };
    fetchCertificados();
  }, []);

  const certificadosFiltrados = filtroAtivo === 'all' 
    ? certificados 
    : certificados.filter(c => c.categoria === filtroAtivo);

  const FiltroBotao = ({ id, texto }) => (
    <button 
      onClick={() => setFiltroAtivo(id)}
      style={{
        padding: '0.5rem 1rem',
        backgroundColor: filtroAtivo === id ? 'var(--primary-color)' : 'transparent',
        color: filtroAtivo === id ? 'var(--background-dark)' : 'var(--text-primary-dark)',
        border: '1px solid var(--primary-color)',
        borderRadius: '20px',
        cursor: 'pointer',
        transition: 'all 0.3s'
      }}
    >
      {texto}
    </button>
  );

  return (
    <>
      <Head>
        <title>Certificados | Nicolas Almir</title>
      </Head>
      <Header />
      <main className="main-content" style={{ minHeight: '80vh', paddingBottom: '4rem' }}>
        <h1 className="page-title" style={{ textAlign: 'center', color: 'var(--primary-color)', marginBottom: '1rem', fontSize: '2.5rem' }}>Meus Certificados</h1>
        <p style={{ textAlign: 'center', color: 'var(--text-secondary-dark)', marginBottom: '2rem' }}>Documentação das minhas conquistas.</p>

        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '1rem', justifyContent: 'center', marginBottom: '3rem' }}>
          <FiltroBotao id="all" texto="Todos" />
          <FiltroBotao id="programming" texto="Programação" />
          <FiltroBotao id="ai" texto="IA" />
          <FiltroBotao id="web" texto="Web" />
          <FiltroBotao id="hardware" texto="Hardware" />
          <FiltroBotao id="data" texto="Dados" />
          <FiltroBotao id="business" texto="Business" />
        </div>

        {loading ? (
          <p style={{ textAlign: 'center', color: 'var(--primary-color)' }}>Carregando dados da Matrix...</p>
        ) : (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '2rem' }}>
            {certificadosFiltrados.map(cert => (
              <div key={cert.id} style={{ backgroundColor: 'var(--surface-dark)', borderRadius: '8px', overflow: 'hidden', border: '1px solid var(--secondary-color)', display: 'flex', flexDirection: 'column' }}>
                
                <div style={{ height: '180px', backgroundColor: '#1A1A1A', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  {cert.tipo_arquivo === 'png' || cert.tipo_arquivo === 'jpeg' ? (
                    <img src={cert.url_arquivo} alt={cert.titulo} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                  ) : (
                    <i className="fas fa-file-pdf" style={{ fontSize: '4rem', color: '#e74c3c' }}></i>
                  )}
                </div>

                <div style={{ padding: '1.5rem', flex: 1, display: 'flex', flexDirection: 'column' }}>
                  <h3 style={{ color: 'white', marginBottom: '0.5rem', fontSize: '1.2rem' }}>{cert.titulo}</h3>
                  <p style={{ color: '#a1a1a1', fontSize: '0.9rem', marginBottom: '0.5rem' }}>{cert.emissor}</p>
                  <p style={{ color: '#a1a1a1', fontSize: '0.8rem', marginBottom: '1.5rem' }}>
                    {cert.data_conclusao ? new Date(cert.data_conclusao).toLocaleDateString('pt-BR', {timeZone: 'UTC'}) : 'Data não informada'}
                  </p>
                  
                  <div style={{ marginTop: 'auto' }}>
                    <a href={cert.url_arquivo} target="_blank" rel="noopener noreferrer" className="btn secondary" style={{ width: '100%', display: 'flex', justifyContent: 'center', gap: '0.5rem', alignItems: 'center' }} download>
                      <i className="fas fa-download"></i> Download
                    </a>
                  </div>
                </div>

              </div>
            ))}
            {certificadosFiltrados.length === 0 && (
              <p style={{ gridColumn: '1 / -1', textAlign: 'center', color: '#a1a1a1' }}>Nenhum certificado encontrado nesta categoria.</p>
            )}
          </div>
        )}
      </main>
      <Footer />
    </>
  );
}
